                    <td>@shipment.Description</td>
                    <td>@shipment.Destination</td>
                    <td>
                        <span class="badge @GetStatusBadgeClass(shipment.Status)">
                            @shipment.Status
                        </span>
                    </td>
                    <td>@shipment.EstimatedDelivery?.ToString("yyyy-MM-dd")</td>
                    <td>
                        <select class="form-select form-select-sm" style="width: auto; display: inline-block;"
                                value="@shipment.Status"
                                @onchange="e => UpdateStatus(shipment, e.Value?.ToString() ?? shipment.Status)">
                            @foreach (var status in ShipmentStatuses.All)
                            {
                                <option value="@status">@status</option>
                            }
                        </select>
                    </td>
                </tr>
            }
        </tbody>
    </table>

    @if (!FilteredShipments.Any())
    {
        <p class="text-muted">No shipments match your filters.</p>
    }
}

@code {
    private List<ShipmentDto>? shipments;
    private string filterText = "";
    private string statusFilter = "";
    private bool showCreateForm;
    private bool creating;
    private ShipmentDto newShipment = new();

    private IEnumerable<ShipmentDto> FilteredShipments =>
        (shipments ?? []).Where(s =>
            (string.IsNullOrEmpty(filterText) || s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase)) &&
            (string.IsNullOrEmpty(statusFilter) || s.Status == statusFilter));

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private void ShowCreateForm() => showCreateForm = !showCreateForm;

    private async Task CreateShipment()
    {
        if (string.IsNullOrWhiteSpace(newShipment.Destination))
            return;

        creating = true;
        var created = await ShipmentService.CreateShipmentAsync(newShipment);
        shipments?.Insert(0, created);
        newShipment = new();
        showCreateForm = false;
        creating = false;
    }

    private async Task UpdateStatus(ShipmentDto shipment, string newStatus)
    {
        if (shipment.Status == newStatus) return;
        await ShipmentService.UpdateStatusAsync(shipment.Id, newStatus);
        shipment.Status = newStatus;
    }

    private static string GetStatusBadgeClass(string status) => status switch
    {
        ShipmentStatuses.Pending => "bg-secondary",
        ShipmentStatuses.InTransit => "bg-info text-dark",
        ShipmentStatuses.OutForDelivery => "bg-warning text-dark",
        ShipmentStatuses.Delivered => "bg-success",
        ShipmentStatuses.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };
}

@page "/track"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@inject IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<h1>Track Your Shipment</h1>
<p>Enter your tracking number below to check delivery status.</p>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="e.g. SHP-20260601-123456"
                   @bind="trackingNumber" @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="Search" disabled="@searching">
                @(searching ? "Searching..." : "Track")
            </button>
        </div>
    </div>
</div>

@if (searched && shipment is null)
{
    <div class="alert alert-warning">
        <strong>Not found.</strong> No shipment matches tracking number "<em>@searchedNumber</em>".
        Please double-check and try again.
    </div>
}

@if (shipment is not null)
{
    <div class="card">
        <div class="card-header">
            <strong>Tracking #:</strong> <code>@shipment.TrackingNumber</code>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <dl>
                        <dt>Status</dt>
                        <dd>
                            <span class="badge @GetStatusBadgeClass(shipment.Status) fs-6">
                                @shipment.Status
                            </span>
                        </dd>

                        <dt>Destination</dt>
                        <dd>@shipment.Destination</dd>

                        <dt>Description</dt>
                        <dd>@(string.IsNullOrEmpty(shipment.Description) ? "—" : shipment.Description)</dd>
                    </dl>
                </div>
                <div class="col-md-6">
                    <dl>
                        <dt>Estimated Delivery</dt>
                        <dd>
                            @if (shipment.EstimatedDelivery.HasValue)
                            {
                                <span class="fs-5">@shipment.EstimatedDelivery.Value.ToString("dddd, MMMM d, yyyy")</span>
                            }
                            else
                            {
                                <span class="text-muted">Not yet available</span>
                            }
                        </dd>

                        <dt>Shipped On</dt>
                        <dd>@shipment.CreatedAt.ToString("MMMM d, yyyy")</dd>
                    </dl>
                </div>
            </div>
        </div>
    </div>
}

@code {
    private string trackingNumber = "";
    private string searchedNumber = "";
    private ShipmentDto? shipment;
    private bool searching;
    private bool searched;

    private async Task Search()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber))
            return;

        searching = true;
        searched = false;
        shipment = null;

        shipment = await ShipmentService.GetByTrackingNumberAsync(trackingNumber.Trim());
        searchedNumber = trackingNumber.Trim();
        searched = true;
        searching = false;
    }

    private async Task HandleKeyDown(Microsoft.AspNetCore.Components.Web.KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await Search();
    }

    private static string GetStatusBadgeClass(string status) => status switch
    {
        ShipmentStatuses.Pending => "bg-secondary",
        ShipmentStatuses.InTransit => "bg-info text-dark",
        ShipmentStatuses.OutForDelivery => "bg-warning text-dark",
        ShipmentStatuses.Delivered => "bg-success",
        ShipmentStatuses.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };
}

